#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# G016 stage 0, one run (box3900x, detached): an IBD-like long sync of the .6 release monerod from a local source node,
# 3,106,400 -> 3,123,269 (16,869 blocks; the source snapshot h3123270 holds 3,123,270 blocks, top 3,123,269), in a systemd scope with MemoryMax=<level>, with every bio on dm-0 traced.
# No the reference node traffic: the source is a stock beta31 node on the synced snapshot copy, 127.0.0.1:28180, no outbound peers.
# The control box restores the working DB to stressnet_h3106400 before each run (snapctl.sh restore).
# Not a timing run for the HDD: the disk is box3900x's SSD. What it measures: which pages the node reads from disk,
# by LMDB table, per block, at each memory level; and its CPU time per block.
# EXTRA_ARGS: more monerod arguments (G016 W-A: --block-sync-size). PERF=1 [PERF_AT=<blocks in>] [PERF_S=<s>]: a call-graph profile.
# NODE_WRAP: a command put before the test node's binary (G016 s0w: taskset -c 0-3).
# usage: [NODE_WRAP=<cmd>] [TOP=<height>] [RESID=1] [BIN_OVERRIDE=<binary>] [EXTRA_ARGS=<args>] g016s0_run.sh <name> <MemoryMax value or infinity>      Marker G016S0_RUN_DONE in $O/run.log.
set -u
name=$1; level=$2
G=$HOME/work/g016; A=$HOME/work/research-artifacts; O=$A/g016s0/$name
DD=$HOME/work/chains/stressnet; DF=$DD/testnet/lmdb/data.mdb
SRCDD=$A/snapshots/stressnet_synced_h3123270; STOCK=$HOME/work/monero-fcmp/build/beta31/bin/monerod
BIN=${BIN_OVERRIDE:-$A/dot6/monerod-dot6}; [ -n "$BIN" ] || BIN=$A/dot6/monerod-dot6; TOP=${TOP:-3123269}; START=3106400; UNIT=g016s0-$name; RUN_TIMEOUT=${RUN_TIMEOUT:-18000}
P=$HOME/work/g015proto
[ -x "$BIN" ] && [ -x "$STOCK" ] && [ -x "$G/pagemap" ] && [ -f "$G/bioread.bt" ] && [ -f "$G/sampler.py" ] && [ -f "$SRCDD/testnet/lmdb/data.mdb" ] && [ -f "$DF" ] \
  || { echo "ABORT: not on the work box"; exit 1; }
[ -e "$O" ] && { echo "ABORT: $O exists"; exit 1; }
mkdir -p $O; L=$O/run.log
log() { echo "$(date -u +%FT%TZ) $*" >> $L; }
fin() { log "G016S0_RUN_DONE $1"; exit 0; }
log "extra monerod args: ${EXTRA_ARGS:-none}"
log "start $name level $level; binary $(sha256sum $BIN | cut -c1-16) $($BIN --version | tail -1)"
pgrep -u $USER -x monerod > /dev/null && { log "ABORT a monerod is running"; fin abort; }
pgrep -x shadow > /dev/null && { log "ABORT shadow lanes are running"; fin abort; }
log "load $(cut -d' ' -f1-3 /proc/loadavg); free GB $(df --output=avail -BG $HOME | tail -1)"
rm -f $DD/testnet/lmdb/lock.mdb $SRCDD/testnet/lmdb/lock.mdb
# the start map (reads every tree page once), then nothing of either DB left in the page cache
$G/pagemap $DD/testnet/lmdb $O/map_start.txt > $O/map_start.summary 2>&1 || { log "ABORT pagemap start rc $?"; fin abort; }
log "start map: $(head -1 $O/map_start.summary)"
sync; sudo sysctl -q vm.drop_caches=3
DA0=$(sysctl -n kernel.task_delayacct); sudo sysctl -q kernel.task_delayacct=1
log "after drop: data.mdb $($P/residents $DF /dev/null)"
# the source node
(setsid nohup nice -n 5 $STOCK --testnet --data-dir $SRCDD --p2p-bind-ip 127.0.0.1 --p2p-bind-port 28180 --hide-my-port \
  --out-peers 0 --in-peers 4 --add-exclusive-node 127.0.0.1:1 --no-zmq --non-interactive --no-igd --rpc-bind-ip 127.0.0.1 --rpc-bind-port 28181 \
  --log-file $O/source.log --log-level 0 > $O/source.stdout 2>&1 &)
for i in $(seq 1 300); do curl -s -m 3 http://127.0.0.1:28181/get_height | grep -q '"height"' && break; sleep 1; done
sh=$(curl -s -m 5 http://127.0.0.1:28181/get_height | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$')
[ "${sh:-0}" -gt $TOP ] || { log "ABORT source height ${sh:-none}"; curl -s -m 30 http://127.0.0.1:28181/stop_daemon > /dev/null; fin abort; }
log "source node up, height $sh"
# the tracer
sudo bpftrace -q $G/bioread.bt > $O/bio.txt 2> $O/bio.err &
sleep 5; BTP=$(pgrep -f "^bpftrace -q $G/bioread.bt" | head -1)
[ -n "$BTP" ] || { log "ABORT the tracer did not start: $(head -c 300 $O/bio.err)"; curl -s -m 30 http://127.0.0.1:28181/stop_daemon > /dev/null; fin abort; }
log "tracer pid $BTP"
# the test node, in a scope
mono0=$(python3 -I -c 'import time; print(time.monotonic_ns())'); t0=$(date +%s)
sudo systemd-run --quiet --scope --unit=$UNIT -p MemoryMax=$level -p MemorySwapMax=0 -- runuser -u $USER -- ${NODE_WRAP:-} \
  $BIN --testnet --data-dir $DD --add-exclusive-node 127.0.0.1:28180 --p2p-bind-ip 127.0.0.1 --no-igd --no-zmq --non-interactive \
  --rpc-bind-ip 127.0.0.1 --rpc-bind-port 28081 --log-file $O/node.log --log-level 0 ${EXTRA_ARGS:-} > $O/node.stdout 2>&1 &
NP=; for i in $(seq 1 120); do NP=$(pgrep -u $USER -f "^$BIN --testnet --data-dir $DD " | head -1); [ -n "$NP" ] && break; sleep 0.5; done
[ -n "$NP" ] || { log "ABORT the test node did not start"; fin abort; }
CG=/sys/fs/cgroup$(systemctl show -p ControlGroup --value $UNIT.scope)
log "test node pid $NP, mono0 $mono0, cgroup $CG ($(cat $CG/memory.max 2>/dev/null))"
[ -n "${NODE_WRAP:-}" ] && log "node wrap: $NODE_WRAP; affinity $(taskset -pc $NP 2>&1 | sed 's/.*: //')"
python3 -I $G/sampler.py 28081 $NP $O/samples.csv $CG &
SP=$!
h=0; why=timeout; PF=; PERF_AT=${PERF_AT:-1200}
while [ $(( $(date +%s) - t0 )) -lt $RUN_TIMEOUT ]; do
  sleep 10
  kill -0 $NP 2>/dev/null || { why=exited; break; }
  h=$(curl -s -m 5 http://127.0.0.1:28081/get_height | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$'); h=${h:-0}
  [ "$h" -gt $TOP ] && { why=top; break; }
  # PERF=1: one call-graph profile of the test node (DWARF unwinding, PERF_STACK bytes of stack (default 8192), 49 Hz, CLOCK_MONOTONIC timestamps, PERF_S s), once its height reaches START+PERF_AT (PERF_AT may be negative)
  if [ -n "${PERF:-}" ] && [ -z "$PF" ] && [ "$h" -ge $((START + PERF_AT)) ]; then
    sudo perf record -F 49 -k CLOCK_MONOTONIC --call-graph dwarf,${PERF_STACK:-8192} -p $NP -o $O/perf.data -- sleep ${PERF_S:-30} > $O/perf.out 2>&1 &
    PF=$!; log "perf started at height $h"
  fi
done
[ -n "$PF" ] && { wait $PF; sudo chown $USER: $O/perf.data; log "perf done: $(grep -o "Captured.*" $O/perf.out | head -1)"; }
t1=$(date +%s)
log "end: $why at height $h after $((t1 - t0)) s from launch"
log "memory: peak $(cat $CG/memory.peak 2>/dev/null) events $(tr '\n' ' ' < $CG/memory.events 2>/dev/null)"
curl -s -m 30 http://127.0.0.1:28081/stop_daemon > /dev/null
for i in $(seq 1 300); do kill -0 $NP 2>/dev/null || break; sleep 1; done
kill -0 $NP 2>/dev/null && { log "test node still up, TERM"; kill -TERM $NP; sleep 30; }
kill $SP 2>/dev/null; wait $SP 2>/dev/null
sudo pkill -INT -f "^bpftrace -q $G/bioread.bt"; sleep 3
log "tracer lines $(wc -l < $O/bio.txt); errors: $(head -c 300 $O/bio.err | tr '\n' ' ')"
curl -s -m 30 http://127.0.0.1:28181/stop_daemon > /dev/null
for i in $(seq 1 300); do pgrep -u $USER -x monerod > /dev/null || break; sleep 1; done
log "monerod processes left: $(pgrep -u $USER -x monerod | wc -l)"
sudo sysctl -q kernel.task_delayacct=$DA0; log "task_delayacct back to $(sysctl -n kernel.task_delayacct)"
# RESID=1: which pages of data.mdb the page cache holds once the node has stopped (labelled later by the end map)
[ -n "${RESID:-}" ] && log "resident at the end: $($P/residents $DF $O/resident_end.txt)"
rm -f $DD/testnet/lmdb/lock.mdb
filefrag -v $DF > $O/fiemap.txt 2>&1
$G/pagemap $DD/testnet/lmdb $O/map_end.txt > $O/map_end.summary 2>&1; log "end map rc $?: $(head -1 $O/map_end.summary)"
[ -x $G/pagemap2 ] && { $G/pagemap2 $DD/testnet/lmdb $O/map_end_types.txt > $O/map_end_types.summary 2>&1; log "end type map rc $?"; }
log "node log: Synced lines $(grep -c 'Synced ' $O/node.log), ERROR $(grep -c '	ERROR	' $O/node.log), warm-up: $(grep -o 'Index warm-up: read.*' $O/node.log | head -1 | cut -c1-120) $(grep -o 'LMDB G016 drop-freed: .*' $O/node.stdout 2>/dev/null | tail -1)"
fin $why
